const {registerReplayGate}=await import('/901-narrative-combat/work/rules_engine/gm_runtime/replay-gate-script.example.js');
const {createChatSessionAccess,INTEGRATION_SCENE}=await import('/901-narrative-combat/work/rules_engine/gm_runtime/integrated.mjs');
const {createNarrativeSession}=await import('/901-narrative-combat/work/rules_engine/gm_runtime/narrative.mjs');
await waitGlobalInitialized('Mvu');
const response=await fetch('/901-narrative-combat/work/character_builder/real_character/yulinfeng_replay_t0.baseline.json');
if(!response.ok)throw Error('人物来源未安装');
const baseline=await response.json();
const style=await (await fetch('/901-narrative-combat/narrative-style.json')).json();
const narrationRules='你是901的主持，用原团的文字方式续写战斗。程序事实已经结算，不要再次裁定。'+
  '把动作按先后写成连贯场面：出手手段、相对位置、对方如何应付、落定后的局面。用具体的剑路、拳势、脚下和环境反馈承载因果，避免报表、招式清单和每击都写决战。'+
  '不要只用一句命中/受伤带过。少量事件写一至三段，整场旁观演练按关键攻防展开，保留转折。已经发生的事情才能写成事实。'+
  '御临风的动作、话语和意图以玩家声明为限，不能替他补动作、台词和心理。对手的闪避、架挡、踉跄是既定结果的表现，不能凭描写追加一次攻击、移动、施法或消耗。'+
  '尤其在等待御临风声明、或玩家明确说尚不行动时，不写他握剑、转腕、变换姿势、挪步、调息等新增动作；只描述对手和既有环境。不得把背景资料中的法师塔、城墙等补进这个开阔演练场。'+
  'participants.position是米坐标，描述距离必须与之相符。没有移动事件就没有站位变化，受伤只能写躯干晃动、伤口等，不能写后退数步、突进、击飞；没有使用能力的事件也不能补写运气施法或新的招式。'+
  '按events顺序描写，不能把攻击后的移动挪到攻击之前。consequence逐条成立，特别是御临风受伤时不能因玩家说了格挡就写成尽数挡下。只为participants中有事实支持的人描写本轮动作，不补场边人物的反应。'+
  '等待玩家借机攻击声明时，对方只是准备离开威胁范围；不要先移动他，也不要替御临风发动借机攻击。'+
  '仅写events和participants支持的结果。无新增事件时只承接对话与扮演，不发生新的机械行为。'+
  '这是御临风的观察视角。队友和敌人的生命、能量、属性、攻防、技能预算、骰数和隐藏增益一律不可公开或猜测；只描述可见伤势与动作。'+
  'phase为等待玩家继续行动时停在当下，剩余动作由玩家继续声明。phase为等待玩家受击反应时攻击尚未命中，停在来势上，等玩家声明如何防御；不得替他闪避、格挡或使用能力。'+
  '战斗结束才写战后即时反应，不擅自恢复、授予奖励或推进下一幕。不输出选项菜单、规则表、变量或数值面板，程序会附上御临风自己的状态。';
const modelOptions={should_stream:false,should_silence:true,max_chat_history:6,
  ordered_prompts:['world_info_before','char_description','scenario',
    {role:'system',content:INTEGRATION_SCENE+'只公开御临风自己的数值；同伴和敌人仅有可观察表现。JS独占规则写回。'},
    'world_info_after','chat_history','user_input']};
const getSession=createChatSessionAccess(()=>SillyTavern,tavern=>createNarrativeSession({
  baseline,mvu:Mvu,tavern,generateRaw,createChatMessages,setChatMessages,
  narrate:facts=>generateRaw({should_stream:false,should_silence:true,max_chat_history:0,
    ordered_prompts:[{role:'system',content:style+'\n\n'+narrationRules},'user_input'],
    user_input:JSON.stringify(facts)}),
}));
const combat={
  get busy(){return getSession().busy;},
  get encounterOptions(){return getSession().encounterOptions;},
  resumeEntry:p=>getSession().resumeEntry(p),
  handleTurn:input=>getSession().handleTurn(input),
  handleFailure:input=>getSession().handleFailure(input),
  enterForPlayer:(id,p)=>getSession().enterForPlayer(id,p),
};
registerReplayGate({getMvu:async()=>Mvu,combat,
  profile:{debug:false,prepare:()=>getSession().prepare(),loadBaseline:async()=>getSession().baseline,directEffects:false,
    sceneContext:INTEGRATION_SCENE,classificationTimeoutMs:60000,modelOptions,
    narrationInstruction:'用原团式文字承接当前场景。只描述队友和敌人的可见表现，不公开其数值；不自动开战，不替御临风说话或决定。'}});
window.addEventListener('pagehide',()=>{try{getSession().dispose();}catch{}});
